toolUseResult.content:
{
  "openapi": "3.1.0",
  "info": {
    "title": "Conference registration API",
    "version": "1.0.0",
    "description": "Contract between the frontend or organizer and the backend. Specification: docs/02_specification.md sections 4, 8, 9."
  },
  "servers": [{ "url": "/" }],
  "paths": {
    "/api/form-config": {
      "get": {
        "operationId": "getFormConfig",
        "summary": "Form configuration: active options, consents, reCAPTCHA site key (AC-003-01)",
        "responses": {
          "200": {
            "description": "Configuration",
            "content": { "application/json": { "schema": { "$ref": "#/components/schemas/FormConfig" } } }
          },
          "429": { "$ref": "#/components/responses/TooManyRequests" }
        }
      }
    },
    "/api/registrations": {
      "post": {
        "operationId": "createRegistration",
        "summary": "Submit a registration (US-001, US-002)",
        "requestBody": {
          "required": true,
          "content": { "application/json": { "schema": { "$ref": "#/components/schemas/RegistrationRequest" } } }
        },
        "responses": {
          "201": {
            "description": "Accepted, stored in the database and as JSON copy",
            "content": { "application/json": { "schema": { "$ref": "#/components/schemas/RegistrationCreated" } } }
          },
          "400": {
            "description": "Rejected: field errors (validation or reCAPTCHA) or malformed JSON; nothing stored, nothing sent",
            "content": { "application/json": { "schema": { "$ref": "#/components/schemas/Error" } } }
          },
          "413": {
            "description": "Body larger than the configured limit",
            "content": { "application/json": { "schema": { "$ref": "#/components/schemas/Error" } } }
          },
          "429": { "$ref": "#/components/responses/TooManyRequests" },
          "500": {
            "description": "Could not be stored (for example JSON copy not writable); nothing left in the database",
            "content": { "application/json": { "schema": { "$ref": "#/components/schemas/Error" } } }
          }
        }
      }
    },
    "/api/export": {
      "get": {
        "operationId": "exportRegistrations",
        "summary": "Excel export for organizers (US-008)",
        "security": [{ "organizerBasic": [] }],
        "responses": {
          "200": {
            "description": "Workbook with one row per registration",
            "headers": {
              "Content-Disposition": {
                "schema": { "type": "string", "const": "attachment; filename=\"registrations.xlsx\"" }
              }
            },
            "content": {
              "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet": {
                "schema": { "type": "string", "format": "binary" }
              }
            }
          },
          "401": {
            "description": "Missing or wrong credentials; no registration data",
            "headers": { "WWW-Authenticate": { "schema": { "type": "string" } } }
          },
          "403": {
            "description": "Plain HTTP from a non-loopback client while HTTPS-only is on (SR-06, D-10)",
            "content": { "application/json": { "schema": { "$ref": "#/components/schemas/Error" } } }
          },
          "429": { "$ref": "#/components/responses/TooManyRequests" }
        }
      }
    }
  },
  "components": {
    "securitySchemes": {
      "organizerBasic": { "type": "http", "scheme": "basic" }
    },
    "responses": {
      "TooManyRequests": {
        "description": "Rate limit per client exceeded",
        "content": { "application/json": { "schema": { "$ref": "#/components/schemas/Error" } } }
      }
    },
    "schemas": {
      "RegistrationType": { "type": "string", "enum": ["EXTERNAL", "STUDENT"] },
      "Category": { "type": "string", "enum": ["WORKSHOP", "EVENT", "MEAL", "OTHER"] },
      "FormConfig": {
        "type": "object",
        "required": ["conferenceName", "recaptcha", "options", "consents"],
        "additionalProperties": false,
        "properties": {
          "conferenceName": { "type": "string" },
          "recaptcha": {
            "type": "object",
            "required": ["siteKey", "testMode"],
            "additionalProperties": false,
            "properties": {
              "siteKey": { "type": "string" },
              "testMode": { "type": "boolean" }
            }
          },
          "options": { "type": "array", "items": { "$ref": "#/components/schemas/Option" } },
          "consents": { "type": "array", "items": { "$ref": "#/components/schemas/Consent" } }
        }
      },
      "Option": {
        "type": "object",
        "required": ["id", "name", "category", "availableTo"],
        "additionalProperties": false,
        "properties": {
          "id": { "type": "string" },
          "name": { "type": "string" },
          "category": { "$ref": "#/components/schemas/Category" },
          "availableTo": {
            "type": "array",
            "minItems": 1,
            "items": { "$ref": "#/components/schemas/RegistrationType" }
          }
        }
      },
      "Consent": {
        "type": "object",
        "required": ["id", "text", "mandatory"],
        "additionalProperties": false,
        "properties": {
          "id": { "type": "string" },
          "text": { "type": "string" },
          "mandatory": { "type": "boolean" }
        }
      },
      "RegistrationRequest": {
        "type": "object",
        "description": "Text fields are trimmed. EXTERNAL requires organization; STUDENT requires studyInstitution, studyProgramme, studentId; fields of the other type must be absent or blank.",
        "properties": {
          "type": { "$ref": "#/components/schemas/RegistrationType" },
          "firstName": { "type": "string", "maxLength": 100 },
          "lastName": { "type": "string", "maxLength": 100 },
          "email": { "type": "string", "format": "email", "maxLength": 254 },
          "organization": { "type": "string", "maxLength": 200 },
          "studyInstitution": { "type": "string", "maxLength": 200 },
          "studyProgramme": { "type": "string", "maxLength": 200 },
          "studentId": { "type": "string", "maxLength": 50 },
          "optionIds": { "type": "array", "items": { "type": "string" }, "uniqueItems": true },
          "consents": { "type": "array", "items": { "type": "string" }, "description": "Ids of the consents given" },
          "recaptchaToken": { "type": "string" }
        }
      },
      "RegistrationCreated": {
        "type": "object",
        "required": ["id", "type", "firstName", "lastName", "options", "registeredAt"],
        "properties": {
          "id": { "type": "string", "format": "uuid" },
          "type": { "$ref": "#/components/schemas/RegistrationType" },
          "firstName": { "type": "string" },
          "lastName": { "type": "string" },
          "options": {
            "type": "array",
            "items": {
              "type": "object",
              "required": ["id", "name", "category"],
              "properties": {
                "id": { "type": "string" },
                "name": { "type": "string" },
                "category": { "$ref": "#/components/schemas/Category" }
              }
            }
          },
          "registeredAt": { "type": "string", "format": "date-time" }
        }
      },
      "FieldError": {
        "type": "object",
        "required": ["field", "message"],
        "properties": {
          "field": {
            "type": "string",
            "description": "type, firstName, lastName, email, organization, studyInstitution, studyProgramme, studentId, optionIds, consents, consents.<id>, recaptchaToken"
          },
          "message": { "type": "string" }
        }
      },
      "Error": {
        "type": "object",
        "required": ["message"],
        "properties": {
          "message": { "type": "string" },
          "fieldErrors": { "type": "array", "items": { "$ref": "#/components/schemas/FieldError" } }
        }
      }
    }
  }
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "conference-config.schema.json",
  "title": "Conference configuration (options and consents)",
  "description": "Loaded at backend startup from CONFERENCE_CONFIG (specification section 3). Additional startup rules: option ids unique, consent ids unique; any violation stops the application (AC-003-03).",
  "type": "object",
  "required": ["options", "consents"],
  "additionalProperties": false,
  "properties": {
    "options": {
      "type": "array",
      "items": {
        "type": "object",
        "required": ["id", "name", "category"],
        "additionalProperties": false,
        "properties": {
          "id": { "type": "string", "pattern": "^[a-z0-9][a-z0-9-]{0,63}$" },
          "name": { "type": "string", "minLength": 1, "maxLength": 200 },
          "category": { "type": "string", "enum": ["WORKSHOP", "EVENT", "MEAL", "OTHER"] },
          "active": { "type": "boolean", "default": true },
          "availableTo": {
            "type": "array",
            "minItems": 1,
            "uniqueItems": true,
            "items": { "type": "string", "enum": ["EXTERNAL", "STUDENT"] },
            "default": ["EXTERNAL", "STUDENT"]
          }
        }
      }
    },
    "consents": {
      "type": "array",
      "items": {
        "type": "object",
        "required": ["id", "text", "mandatory"],
        "additionalProperties": false,
        "properties": {
          "id": { "type": "string", "pattern": "^[a-z0-9][a-z0-9-]{0,63}$" },
          "text": { "type": "string", "minLength": 1 },
          "mandatory": { "type": "boolean" }
        }
      }
    }
  },
  "examples": [
    {
      "options": [
        { "id": "ws-testing", "name": "Workshop: Software testing", "category": "WORKSHOP" },
        { "id": "meal-dinner", "name": "Conference dinner", "category": "MEAL", "availableTo": ["EXTERNAL"] },
        { "id": "ws-legacy", "name": "Legacy workshop", "category": "WORKSHOP", "active": false }
      ],
      "consents": [
        {
          "id": "privacy",
          "text": "I agree that my personal data is processed for organizing the conference and that it is shared with the conference organizers.",
          "mandatory": true
        }
      ]
    }
  ]
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "registration-copy.schema.json",
  "title": "Raw JSON copy of an accepted registration",
  "description": "File <JSON_COPY_DIR>/<id>.json, UTF-8, written before the database commit (specification 5.3, 5.4). The organizer notification attaches the same bytes (AC-007-02). Fields of the other registration type are absent.",
  "type": "object",
  "required": ["id", "type", "firstName", "lastName", "email", "options", "consents", "registeredAt"],
  "additionalProperties": false,
  "properties": {
    "id": { "type": "string", "format": "uuid" },
    "type": { "type": "string", "enum": ["EXTERNAL", "STUDENT"] },
    "firstName": { "type": "string" },
    "lastName": { "type": "string" },
    "email": { "type": "string" },
    "organization": { "type": "string" },
    "studyInstitution": { "type": "string" },
    "studyProgramme": { "type": "string" },
    "studentId": { "type": "string" },
    "options": {
      "type": "array",
      "items": {
        "type": "object",
        "required": ["id", "name", "category"],
        "additionalProperties": false,
        "properties": {
          "id": { "type": "string" },
          "name": { "type": "string" },
          "category": { "type": "string", "enum": ["WORKSHOP", "EVENT", "MEAL", "OTHER"] }
        }
      }
    },
    "consents": {
      "type": "array",
      "items": {
        "type": "object",
        "required": ["id", "text", "givenAt"],
        "additionalProperties": false,
        "properties": {
          "id": { "type": "string" },
          "text": { "type": "string" },
          "givenAt": { "type": "string", "format": "date-time" }
        }
      }
    },
    "registeredAt": { "type": "string", "format": "date-time" }
  },
  "allOf": [
    {
      "if": { "properties": { "type": { "const": "EXTERNAL" } } },
      "then": { "required": ["organization"] }
    },
    {
      "if": { "properties": { "type": { "const": "STUDENT" } } },
      "then": { "required": ["studyInstitution", "studyProgramme", "studentId"] }
    }
  ]
}

{
  "contract": "anti-automation",
  "description": "Google reCAPTCHA v2 between frontend, backend and Google (specification section 7, SR-01, SR-02).",
  "frontend": {
    "productionWidget": {
      "script": "https://www.google.com/recaptcha/api.js?render=explicit",
      "siteKeySource": "GET /api/form-config -> recaptcha.siteKey",
      "tokenField": "recaptchaToken"
    },
    "testMode": {
      "when": "GET /api/form-config -> recaptcha.testMode == true",
      "control": "checkbox labelled 'I am not a robot (test mode)'",
      "token": "test-pass"
    }
  },
  "backend": {
    "verifyRequest": {
      "method": "POST",
      "url": "RECAPTCHA_VERIFY_URL (default https://www.google.com/recaptcha/api/siteverify)",
      "contentType": "application/x-www-form-urlencoded",
      "fields": { "secret": "RECAPTCHA_SECRET_KEY", "response": "<recaptchaToken>", "remoteip": "<client ip>" },
      "timeoutMillis": 5000
    },
    "verifyResponse": {
      "contentType": "application/json",
      "accepted": { "success": true },
      "rejected": "success false or missing, any non-200 status, unparsable body, I/O error or timeout"
    },
    "testMode": {
      "setting": "RECAPTCHA_TEST_MODE",
      "default": false,
      "accepted": "token equal to 'test-pass'",
      "rejected": "any other token",
      "networkCalls": "none"
    },
    "startupGuard": [
      "refuse to start when RECAPTCHA_TEST_MODE=true and APP_ENVIRONMENT is not 'local' or 'test'",
      "refuse to start when RECAPTCHA_TEST_MODE=false and RECAPTCHA_SITE_KEY or RECAPTCHA_SECRET_KEY is empty"
    ]
  }
}

