package si.konferenca.registration.service;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.util.Arrays;
import java.util.EnumSet;
import java.util.List;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;
import si.konferenca.registration.conference.Category;
import si.konferenca.registration.conference.ConferenceConfiguration;
import si.konferenca.registration.conference.ConferenceOption;
import si.konferenca.registration.conference.ConsentDefinition;
import si.konferenca.registration.domain.ParticipantDetails;
import si.konferenca.registration.domain.RegistrationType;

class RegistrationValidatorTest {

  static final ConferenceOption WORKSHOP =
      new ConferenceOption("ws", "Workshop", Category.WORKSHOP, true, EnumSet.allOf(RegistrationType.class));
  static final ConferenceOption DINNER =
      new ConferenceOption("dinner", "Dinner", Category.MEAL, true, EnumSet.of(RegistrationType.EXTERNAL));
  static final ConferenceOption OLD =
      new ConferenceOption("old", "Old", Category.EVENT, false, EnumSet.allOf(RegistrationType.class));
  static final ConsentDefinition PRIVACY = new ConsentDefinition("privacy", "Privacy", true);
  static final ConsentDefinition PHOTO = new ConsentDefinition("photo", "Photo", false);

  private final RegistrationValidator validator =
      new RegistrationValidator(
          new ConferenceConfiguration(List.of(WORKSHOP, DINNER, OLD), List.of(PRIVACY, PHOTO)));

  static RegistrationCommand external(String... optionIds) {
    return new RegistrationCommand(
        "EXTERNAL", " Ana ", "Novak", "ana@example.org ", "Institut", null, null, null,
        Arrays.asList(optionIds), List.of("privacy"), "token", "1.2.3.4");
  }

  static RegistrationCommand student(String... optionIds) {
    return new RegistrationCommand(
        "STUDENT", "Luka", "Kranjc", "luka@example.org", null, "Univerza", "CS", "6320",
        Arrays.asList(optionIds), List.of("privacy", "photo"), "token", "1.2.3.4");
  }

  private List<FieldError> errors(RegistrationCommand command) {
    try {
      validator.validate(command);
      return List.of();
    } catch (RegistrationRejectedException e) {
      return e.fieldErrors();
    }
  }

  @Test
  void acceptsAndTrimsAnExternalSubmission() {
    ValidatedRegistration valid = validator.validate(external("ws", "dinner"));

    assertThat(valid.type()).isEqualTo(RegistrationType.EXTERNAL);
    assertThat(valid.participant())
        .isEqualTo(
            new ParticipantDetails("Ana", "Novak", "ana@example.org", "Institut", null, null, null));
    assertThat(valid.options()).containsExactly(WORKSHOP, DINNER);
    assertThat(valid.consents()).containsExactly(PRIVACY);
  }

  @Test
  void acceptsAStudentSubmission() {
    ValidatedRegistration valid = validator.validate(student("ws"));

    assertThat(valid.type()).isEqualTo(RegistrationType.STUDENT);
    assertThat(valid.participant())
        .isEqualTo(
            new ParticipantDetails("Luka", "Kranjc", "luka@example.org", null, "Univerza", "CS", "6320"));
    assertThat(valid.consents()).containsExactly(PRIVACY, PHOTO);
  }

  @Test
  void acceptsMissingOptionListAndPaddedType() {
    RegistrationCommand command =
        new RegistrationCommand(
            " STUDENT ", "Luka", "Kranjc", "luka@example.org", "", "U", "P", "1", null,
            List.of("privacy"), "t", null);

    assertThat(validator.validate(command).options()).isEmpty();
  }

  @ParameterizedTest
  @ValueSource(strings = {"GUEST", "external", ""})
  void rejectsUnknownType(String type) {
    RegistrationCommand command =
        new RegistrationCommand(
            type, "A", "B", "a@b.org", "O", null, null, null, List.of("ws"), List.of("privacy"),
            "t", null);

    assertThat(errors(command))
        .containsExactly(new FieldError("type", RegistrationValidator.INVALID_TYPE));
  }

  @Test
  void rejectsMissingTypeAndStillChecksConsentsAndToken() {
    RegistrationCommand command =
        new RegistrationCommand(null, null, null, null, null, null, null, null, null, null, null, null);

    assertThat(errors(command))
        .containsExactly(
            new FieldError("type", RegistrationValidator.INVALID_TYPE),
            new FieldError("consents.privacy", RegistrationValidator.CONSENT_REQUIRED),
            new FieldError("recaptchaToken", RegistrationValidator.TOKEN_REQUIRED));
  }

  @Test
  void reportsEveryMissingFieldOfTheType() {
    RegistrationCommand command =
        new RegistrationCommand(
            "STUDENT", " ", null, "", null, null, "\t", null, List.of(), List.of("privacy"), " ",
            null);

    assertThat(errors(command))
        .containsExactly(
            new FieldError("firstName", RegistrationValidator.REQUIRED),
            new FieldError("lastName", RegistrationValidator.REQUIRED),
            new FieldError("email", RegistrationValidator.REQUIRED),
            new FieldError("studyInstitution", RegistrationValidator.REQUIRED),
            new FieldError("studyProgramme", RegistrationValidator.REQUIRED),
            new FieldError("studentId", RegistrationValidator.REQUIRED),
            new FieldError("recaptchaToken", RegistrationValidator.TOKEN_REQUIRED));
  }

  @Test
  void rejectsFieldsOfTheOtherType() {
    RegistrationCommand external =
        new RegistrationCommand(
            "EXTERNAL", "A", "B", "a@b.org", "O", "U", " ", "1", List.of(), List.of("privacy"),
            "t", null);
    RegistrationCommand student =
        new RegistrationCommand(
            "STUDENT", "A", "B", "a@b.org", "Org", "U", "P", "1", List.of(), List.of("privacy"),
            "t", null);

    assertThat(errors(external))
        .containsExactly(
            new FieldError("studyInstitution", RegistrationValidator.NOT_FOR_TYPE),
            new FieldError("studentId", RegistrationValidator.NOT_FOR_TYPE));
    assertThat(errors(student))
        .containsExactly(new FieldError("organization", RegistrationValidator.NOT_FOR_TYPE));
  }

  @Test
  void enforcesMaximumLengths() {
    RegistrationCommand atLimit =
        new RegistrationCommand(
            "STUDENT", "a".repeat(100), "b".repeat(100), "a".repeat(240) + "@example.org", null,
            "c".repeat(200), "d".repeat(200), "e".repeat(50), List.of(), List.of("privacy"), "t",
            null);
    RegistrationCommand overLimit =
        new RegistrationCommand(
            "STUDENT", "a".repeat(101), "b".repeat(101), "a".repeat(243) + "@example.org", null,
            "c".repeat(201), "d".repeat(201), "e".repeat(51), List.of(), List.of("privacy"), "t",
            null);
    RegistrationCommand longOrganization =
        new RegistrationCommand(
            "EXTERNAL", "A", "B", "a@b.org", "o".repeat(201), null, null, null, List.of(),
            List.of("privacy"), "t", null);

    assertThat(errors(atLimit)).isEmpty();
    assertThat(errors(overLimit))
        .extracting(FieldError::field)
        .containsExactly(
            "firstName", "lastName", "email", "studyInstitution", "studyProgramme", "studentId");
    assertThat(errors(overLimit)).extracting(FieldError::message).containsOnly(RegistrationValidator.TOO_LONG);
    assertThat(errors(longOrganization))
        .containsExactly(new FieldError("organization", RegistrationValidator.TOO_LONG));
  }

  @ParameterizedTest
  @ValueSource(
      strings = {
        "ana",
        "ana@example",
        "a b@example.org",
        "ana@exa mple.org",
        "ana@@example.org",
        "@example.org",
        "ana@.org",
        "ana@example.org.",
        "ana..x@example.org",
        "\"ana@x\"@example.org"
      })
  void rejectsInvalidEmails(String email) {
    assertThat(RegistrationValidator.isValidEmail(email)).isFalse();
  }

  @ParameterizedTest
  @ValueSource(strings = {"ana@example.org", "a.b+c@sub.example.co.uk", "x_y@example.si"})
  void acceptsValidEmails(String email) {
    assertThat(RegistrationValidator.isValidEmail(email)).isTrue();
  }

  @Test
  void reportsInvalidEmailOnTheEmailField() {
    RegistrationCommand command =
        new RegistrationCommand(
            "EXTERNAL", "A", "B", "not-an-email", "O", null, null, null, List.of(),
            List.of("privacy"), "t", null);

    assertThat(errors(command))
        .containsExactly(new FieldError("email", RegistrationValidator.INVALID_EMAIL));
  }

  @Test
  void rejectsUnknownInactiveUnavailableNullAndRepeatedOptions() {
    for (RegistrationCommand command :
        List.of(
            external("ws", "nope"),
            external("old"),
            external("ws", "ws"),
            external("ws", null),
            student("dinner"))) {
      assertThat(errors(command))
          .as(command.optionIds().toString())
          .containsExactly(new FieldError("optionIds", RegistrationValidator.INVALID_OPTIONS));
    }
  }

  @Test
  void checksConsents() {
    RegistrationCommand onlyOptional =
        new RegistrationCommand(
            "EXTERNAL", "A", "B", "a@b.org", "O", null, null, null, List.of(), List.of("photo"),
            "t", null);
    RegistrationCommand unknown =
        new RegistrationCommand(
            "EXTERNAL", "A", "B", "a@b.org", "O", null, null, null, List.of(),
            List.of("privacy", "marketing"), "t", null);
    RegistrationCommand repeated =
        new RegistrationCommand(
            "EXTERNAL", "A", "B", "a@b.org", "O", null, null, null, List.of(),
            List.of("privacy", "privacy"), "t", null);

    assertThat(errors(onlyOptional))
        .containsExactly(new FieldError("consents.privacy", RegistrationValidator.CONSENT_REQUIRED));
    assertThat(errors(unknown))
        .containsExactly(new FieldError("consents", RegistrationValidator.UNKNOWN_CONSENT));
    assertThat(errors(repeated)).isEmpty();
  }

  @Test
  void rejectedExceptionCopiesTheErrors() {
    List<FieldError> errors = new java.util.ArrayList<>(List.of(new FieldError("a", "b")));
    RegistrationRejectedException exception = new RegistrationRejectedException(errors);
    errors.clear();

    assertThat(exception.fieldErrors()).containsExactly(new FieldError("a", "b"));
    assertThatThrownBy(() -> exception.fieldErrors().clear())
        .isInstanceOf(UnsupportedOperationException.class);
  }
}

package si.konferenca.registration.service;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.verifyNoInteractions;
import static org.mockito.Mockito.when;

import java.time.Instant;
import java.time.temporal.ChronoUnit;
import java.util.List;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.mockito.ArgumentCaptor;
import org.springframework.mail.MailSendException;
import si.konferenca.registration.conference.ConferenceConfiguration;
import si.konferenca.registration.domain.GivenConsent;
import si.konferenca.registration.domain.Registration;
import si.konferenca.registration.domain.SelectedOption;
import si.konferenca.registration.infra.MailNotifier;
import si.konferenca.registration.infra.RecaptchaVerifier;
import si.konferenca.registration.service.RegistrationStore.StoredRegistration;

class RegistrationServiceTest {

  private final RecaptchaVerifier recaptcha = mock(RecaptchaVerifier.class);
  private final RegistrationStore store = mock(RegistrationStore.class);
  private final MailNotifier mail = mock(MailNotifier.class);
  private final byte[] copy = {1, 2, 3};
  private RegistrationService service;

  @BeforeEach
  void setUp() {
    RegistrationValidator validator =
        new RegistrationValidator(
            new ConferenceConfiguration(
                List.of(RegistrationValidatorTest.WORKSHOP, RegistrationValidatorTest.DINNER),
                List.of(RegistrationValidatorTest.PRIVACY, RegistrationValidatorTest.PHOTO)));
    service = new RegistrationService(validator, recaptcha, store, mail);
    when(store.save(any())).thenAnswer(i -> new StoredRegistration(i.getArgument(0), copy));
  }

  @Test
  void storesAVerifiedRegistrationThenNotifies() {
    when(recaptcha.verify("token", "1.2.3.4")).thenReturn(true);
    Instant before = Instant.now().truncatedTo(ChronoUnit.MICROS);

    Registration registration =
        service.register(RegistrationValidatorTest.external("ws", "dinner"));

    assertThat(registration.getId()).isNotNull();
    assertThat(registration.getFirstName()).isEqualTo("Ana");
    assertThat(registration.getRegisteredAt())
        .isBetween(before, Instant.now())
        .isEqualTo(registration.getRegisteredAt().truncatedTo(ChronoUnit.MICROS));
    assertThat(registration.getOptions())
        .containsExactly(
            new SelectedOption("ws", "Workshop", "WORKSHOP"),
            new SelectedOption("dinner", "Dinner", "MEAL"));
    assertThat(registration.getConsents())
        .containsExactly(new GivenConsent("privacy", "Privacy", registration.getRegisteredAt()));
    verify(store).save(registration);
    verify(mail).sendParticipantConfirmation(registration);
    verify(mail).sendOrganizerNotifications(registration, copy);
  }

  @Test
  void stripsTheTokenBeforeVerifying() {
    RegistrationCommand command =
        new RegistrationCommand(
            "EXTERNAL", "A", "B", "a@b.org", "O", null, null, null, List.of(),
            List.of("privacy"), " token ", "ip");
    when(recaptcha.verify("token", "ip")).thenReturn(true);

    service.register(command);

    verify(recaptcha).verify("token", "ip");
  }

  @Test
  void rejectsAFailedRecaptchaWithoutStoringOrSending() {
    when(recaptcha.verify(any(), any())).thenReturn(false);

    assertThatThrownBy(() -> service.register(RegistrationValidatorTest.external("ws")))
        .isInstanceOfSatisfying(
            RegistrationRejectedException.class,
            e ->
                assertThat(e.fieldErrors())
                    .containsExactly(
                        new FieldError("recaptchaToken", RegistrationService.RECAPTCHA_REJECTED)));
    verifyNoInteractions(store, mail);
  }

  @Test
  void rejectsInvalidFieldsBeforeCallingTheVerifier() {
    assertThatThrownBy(() -> service.register(RegistrationValidatorTest.external("unknown")))
        .isInstanceOf(RegistrationRejectedException.class);
    verifyNoInteractions(recaptcha, store, mail);
  }

  @Test
  void mailFailuresDoNotUndoTheRegistration() {
    when(recaptcha.verify(any(), any())).thenReturn(true);
    org.mockito.Mockito.doThrow(new MailSendException("down"))
        .when(mail)
        .sendParticipantConfirmation(any());
    when(mail.sendOrganizerNotifications(any(), any())).thenThrow(new MailSendException("down"));

    Registration registration = service.register(RegistrationValidatorTest.external());

    assertThat(registration).isNotNull();
    verify(mail).sendOrganizerNotifications(eq(registration), eq(copy));
  }

  @Test
  void partialOrganizerFailuresAreTolerated() {
    when(recaptcha.verify(any(), any())).thenReturn(true);
    when(mail.sendOrganizerNotifications(any(), any())).thenReturn(1);

    assertThat(service.register(RegistrationValidatorTest.external())).isNotNull();
  }

  @Test
  void storeFailuresPropagateAndNothingIsSent() {
    when(recaptcha.verify(any(), any())).thenReturn(true);
    when(store.save(any())).thenThrow(new java.io.UncheckedIOException(new java.io.IOException()));

    assertThatThrownBy(() -> service.register(RegistrationValidatorTest.external()))
        .isInstanceOf(java.io.UncheckedIOException.class);
    verify(mail, never()).sendParticipantConfirmation(any());
    ArgumentCaptor<Registration> unused = ArgumentCaptor.forClass(Registration.class);
    verify(mail, never()).sendOrganizerNotifications(unused.capture(), any());
  }
}

package si.konferenca.registration.service;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.time.Instant;
import java.util.List;
import java.util.UUID;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.transaction.support.TransactionSynchronization;
import org.springframework.transaction.support.TransactionSynchronizationManager;
import si.konferenca.registration.domain.ParticipantDetails;
import si.konferenca.registration.domain.Registration;
import si.konferenca.registration.domain.RegistrationRepository;
import si.konferenca.registration.domain.RegistrationType;
import si.konferenca.registration.infra.JsonCopyStore;

class RegistrationStoreTest {

  private final RegistrationRepository repository = mock(RegistrationRepository.class);
  private final JsonCopyStore copies = mock(JsonCopyStore.class);
  private final RegistrationStore store = new RegistrationStore(repository, copies);
  private final Registration registration =
      new Registration(
          UUID.randomUUID(),
          RegistrationType.EXTERNAL,
          new ParticipantDetails("A", "B", "a@b.org", "O", null, null, null),
          Instant.now());

  @BeforeEach
  void startSynchronization() {
    TransactionSynchronizationManager.initSynchronization();
  }

  @AfterEach
  void clearSynchronization() {
    TransactionSynchronizationManager.clearSynchronization();
  }

  @Test
  void flushesTheRowThenWritesTheCopy() {
    when(repository.saveAndFlush(registration)).thenReturn(registration);
    when(copies.write(registration)).thenReturn(new byte[] {7});

    RegistrationStore.StoredRegistration stored = store.save(registration);

    assertThat(stored.registration()).isSameAs(registration);
    assertThat(stored.jsonCopy()).containsExactly(7);
    List<TransactionSynchronization> synchronizations =
        TransactionSynchronizationManager.getSynchronizations();
    assertThat(synchronizations).hasSize(1);

    synchronizations.getFirst().afterCompletion(TransactionSynchronization.STATUS_COMMITTED);
    verify(copies, never()).delete(any());
  }

  @Test
  void removesTheCopyWhenTheTransactionDoesNotCommit() {
    when(repository.saveAndFlush(registration)).thenReturn(registration);
    store.save(registration);
    TransactionSynchronization synchronization =
        TransactionSynchronizationManager.getSynchronizations().getFirst();

    synchronization.afterCompletion(TransactionSynchronization.STATUS_ROLLED_BACK);
    synchronization.afterCompletion(TransactionSynchronization.STATUS_UNKNOWN);

    verify(copies, org.mockito.Mockito.times(2)).delete(registration.getId());
  }

  @Test
  void aFailedCopyPropagatesSoTheTransactionRollsBack() {
    when(repository.saveAndFlush(registration)).thenReturn(registration);
    when(copies.write(registration)).thenThrow(new UncheckedIOException(new IOException("x")));

    assertThatThrownBy(() -> store.save(registration)).isInstanceOf(UncheckedIOException.class);
    assertThat(TransactionSynchronizationManager.getSynchronizations()).isEmpty();
  }
}

