        new MockHttpServletRequest("POST", "/api/registrations") {
          @Override
          public ServletInputStream getInputStream() {
            InputStream in = new ByteArrayInputStream(new byte[] {1});
            return new ServletInputStream() {
              @Override
              public int read() throws IOException {
                return in.read();
              }

              @Override
              public void close() {
                closed[0] = true;
              }

              @Override
              public boolean isFinished() {
                return false;
              }

              @Override
              public boolean isReady() {
                return true;
              }

              @Override
              public void setReadListener(jakarta.servlet.ReadListener listener) {}
            };
          }
        };

    new BodySizeLimitFilter(WebTestSupport.properties(true, 1, 10))
        .doFilter(request, new MockHttpServletResponse(), new MockFilterChain());

    assertThat(closed[0]).isTrue();
  }

  // ---- HTTPS-only organizer access ----------------------------------------------------------

  @ParameterizedTest
  @ValueSource(strings = {"127.0.0.1", "127.1.2.3", "::1", "0:0:0:0:0:0:0:1"})
  void loopbackAddresses(String address) {
    assertThat(HttpsOnlyOrganizerFilter.isLoopback(address)).isTrue();
  }

  @ParameterizedTest
  @ValueSource(strings = {"203.0.113.10", "10.0.0.1", "::2", "localhost", "127.0.0.1 ", "[::1]", ""})
  void nonLoopbackAddresses(String address) {
    assertThat(HttpsOnlyOrganizerFilter.isLoopback(address)).isFalse();
  }

  @Test
  void nullAddressIsNotLoopback() {
    assertThat(HttpsOnlyOrganizerFilter.isLoopback(null)).isFalse();
  }

  @Test
  void httpsOnlyRefusesPlainHttpFromRemoteClients() throws Exception {
    HttpsOnlyOrganizerFilter filter =
        new HttpsOnlyOrganizerFilter(WebTestSupport.properties(true, 1, 10));
    MockHttpServletResponse response = new MockHttpServletResponse();
    MockFilterChain chain = new MockFilterChain();

    filter.doFilter(request("GET", "/api/export", "203.0.113.10"), response, chain);

    assertThat(response.getStatus()).isEqualTo(403);
    assertThat(response.getContentAsString()).contains(HttpsOnlyOrganizerFilter.MESSAGE);
    assertThat(response.getHeader("X-Content-Type-Options")).isEqualTo("nosniff");
    assertThat(response.getHeader("Cache-Control")).isEqualTo("no-store");
    assertThat(chain.getRequest()).isNull();
  }

  @Test
  void httpsOnlyPassesSecureLocalAndOtherRequests() throws Exception {
    HttpsOnlyOrganizerFilter filter =
        new HttpsOnlyOrganizerFilter(WebTestSupport.properties(true, 1, 10));
    MockHttpServletRequest secure = request("GET", "/api/export", "203.0.113.10");
    secure.setSecure(true);
    MockHttpServletRequest local = request("GET", "/api/export", "127.0.0.1");
    MockHttpServletRequest other = request("GET", "/api/form-config", "203.0.113.10");

    for (MockHttpServletRequest request : new MockHttpServletRequest[] {secure, local, other}) {
      MockFilterChain chain = new MockFilterChain();
      filter.doFilter(request, new MockHttpServletResponse(), chain);
      assertThat(chain.getRequest()).isSameAs(request);
    }
  }

  @Test
  void httpsOnlyCanBeSwitchedOff() throws Exception {
    HttpsOnlyOrganizerFilter filter =
        new HttpsOnlyOrganizerFilter(WebTestSupport.properties(false, 1, 10));
    MockFilterChain chain = new MockFilterChain();

    filter.doFilter(
        request("GET", "/api/export", "203.0.113.10"), new MockHttpServletResponse(), chain);

    assertThat(chain.getRequest()).isNotNull();
  }
}

package si.konferenca.registration.web;

import static org.assertj.core.api.Assertions.assertThat;

import java.util.List;
import org.junit.jupiter.api.Test;
import org.springframework.http.HttpMethod;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.http.converter.HttpMessageNotReadableException;
import org.springframework.mock.http.MockHttpInputMessage;
import org.springframework.web.HttpRequestMethodNotSupportedException;
import si.konferenca.registration.service.FieldError;
import si.konferenca.registration.service.RegistrationRejectedException;

class ApiExceptionHandlerTest {

  private final ApiExceptionHandler handler = new ApiExceptionHandler();

  @Test
  void rejectedRegistrationsBecome400WithFieldErrors() {
    ResponseEntity<ErrorBody> response =
        handler.rejected(
            new RegistrationRejectedException(
                List.of(new FieldError("email", "bad"), new FieldError("optionIds", "x"))));

    assertThat(response.getStatusCode()).isEqualTo(HttpStatus.BAD_REQUEST);
    assertThat(response.getBody())
        .isEqualTo(
            new ErrorBody(
                ApiExceptionHandler.REJECTED,
                List.of(
                    new ErrorBody.FieldErrorBody("email", "bad"),
                    new ErrorBody.FieldErrorBody("optionIds", "x"))));
  }

  @Test
  void malformedBodiesBecome400WithoutFieldErrors() {
    ResponseEntity<ErrorBody> response =
        handler.malformed(
            new HttpMessageNotReadableException("x", new MockHttpInputMessage(new byte[0])));

    assertThat(response.getStatusCode()).isEqualTo(HttpStatus.BAD_REQUEST);
    assertThat(response.getBody()).isEqualTo(ErrorBody.of(ApiExceptionHandler.MALFORMED));
    assertThat(response.getBody().fieldErrors()).isNull();
  }

  @Test
  void springErrorResponsesKeepTheirStatusWithAGenericMessage() {
    ResponseEntity<ErrorBody> response =
        handler.unexpected(new HttpRequestMethodNotSupportedException(HttpMethod.PUT.name()));

    assertThat(response.getStatusCode()).isEqualTo(HttpStatus.METHOD_NOT_ALLOWED);
    assertThat(response.getBody()).isEqualTo(ErrorBody.of(ApiExceptionHandler.NOT_PROCESSED));
  }

  @Test
  void unexpectedErrorsBecome500WithoutDetails() {
    ResponseEntity<ErrorBody> response =
        handler.unexpected(new IllegalStateException("SQL: insert into registration … secret"));

    assertThat(response.getStatusCode()).isEqualTo(HttpStatus.INTERNAL_SERVER_ERROR);
    assertThat(response.getBody()).isEqualTo(ErrorBody.of(ApiExceptionHandler.GENERIC_ERROR));
  }
}

